import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo, Suspense, useEffect} from 'react'
import {EntryPointContainer} from 'react-relay'

import {useEntryPointLoaderWithEnvironment} from '../../../hooks/relay/useEntryPointLoaderWithEnvironment'
import {getBuildType, getPipeline, getProject} from '../../../selectors'
import type {BuildTypeId, PipelineId, ProjectId} from '../../../types'
import {getProjectBuildTypeFilter} from '../../../types'
import Popup from '../Popup/Popup.lazy'
import {ProjectsPopupEntryPoint} from '../ProjectsPopup/ProjectsPopup.entryPoint'

import {getUrlFormat} from './BreadcrumbsDropdown.utils'

import styles from './BreadcrumbsDropdown.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  buildTypeId?: BuildTypeId
  projectId?: ProjectId
  parentId?: ProjectId
  pipelineId?: PipelineId
  isEditMode?: boolean
}

function BreadcrumbsDropdown({buildTypeId, pipelineId, parentId, projectId, isEditMode}: Props) {
  const parentProjectId = useAppSelector(state => {
    if (pipelineId) {
      return getPipeline(state, pipelineId)?.parentProject.id
    } else if (buildTypeId) {
      return getBuildType(state, buildTypeId)?.projectId
    }

    return getProject(state, projectId)?.parentProjectId
  })
  const activeItem = getProjectBuildTypeFilter({buildTypeId, pipelineId, projectId})
  const [entryPoint, loadEntryPoint, disposeEntryPoint] =
    useEntryPointLoaderWithEnvironment(ProjectsPopupEntryPoint)
  useEffect(() => {
    if (process.env.NODE_ENV === 'test') {
      // load entrypoint for storyshots
      loadEntryPoint(true)
    }
  }, [loadEntryPoint])

  return (
    <Dropdown
      anchor={({active}) => (
        <IconButton
          className={classNames(styles.popupIcon, {[styles.active]: active})}
          iconClassName={styles.iconWrapper}
          title="View siblings"
          icon="chevron-down"
        />
      )}
      onShow={() => loadEntryPoint(true)}
      onHide={disposeEntryPoint}
    >
      {popupProps => (
        <Popup {...popupProps}>
          {entryPoint != null && (
            <Suspense>
              <EntryPointContainer
                entryPointReference={entryPoint}
                props={{
                  ...getUrlFormat(isEditMode),
                  parentProjectId: parentId ?? parentProjectId,
                  activeItem: activeItem && {
                    ...activeItem,
                    group: 'search',
                  },
                  editMode: isEditMode,
                  onClose: popupProps.onCloseAttempt,
                }}
              />
            </Suspense>
          )}
        </Popup>
      )}
    </Dropdown>
  )
}
export default memo(BreadcrumbsDropdown)
