import {graphql, useFragment} from 'react-relay'

import {formatBuildNumber} from '../components/common/BuildNumber/BuildNumber.utils'

import type {useFormatBuildNumberFragment$key} from './__generated__/useFormatBuildNumberFragment.graphql'

const fragment = graphql`
  fragment useFormatBuildNumberFragment on Build {
    number
    state
    queuePosition
  }
`

export default function useFormatBuildNumber(key: useFormatBuildNumberFragment$key | null) {
  const {number, state, queuePosition} = useFragment(fragment, key) ?? {}
  return formatBuildNumber({
    number,
    isQueued: state === 'queued',
    queuePosition,
  }).text
}
