import classNames from 'classnames'
import {useLocation} from 'react-router'

import {getHrefWithQueryParams} from '../../../../routes'
import Icon from '../../Icon/Icon'
import RouterLink from '../../RouterLink/RouterLink'

import styles from './BreadcrumbsLink.module.css'

type Props = {
  name: string
  to?: string
  leftIcon?: string
  className?: string
  active?: boolean
}

export default function BreadcrumbsLink({className, to, name, leftIcon, active}: Props) {
  const common = {
    className: classNames(className, styles.link, {[styles.active]: active}),
  }
  const location = useLocation()
  const href = getHrefWithQueryParams(location, to, ({branch}) => ({branch}))

  const content = (
    <>
      {leftIcon != null ? <Icon name={leftIcon} className={styles.leftIcon} /> : null}
      <span>{name}</span>
    </>
  )

  if (to == null) {
    return <span {...common}>{content}</span>
  }

  return (
    <RouterLink {...common} to={href}>
      {content}
    </RouterLink>
  )
}
