import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'

export function getUrlFormat(isEditMode?: boolean) {
  return {
    buildTypeUrlFormat: resolveRelative(
      isEditMode ? '/admin/editBuild.html?id=buildType:{id}' : '/buildConfiguration/{id}',
    ),
    projectUrlFormat: resolveRelative(
      isEditMode ? '/admin/editProject.html?projectId={id}' : '/project/{id}',
    ),
    pipelineUrlFormat: resolveRelative(isEditMode ? '/pipeline/{id}?edit=true' : '/pipeline/{id}'),
  }
}
